import React from "react";
import { Link } from "react-router-dom";

const Header = () => {
  return (
    <div className="header">
      <header className="header-content">
        <div className="logo">INVENTORY</div>

        <nav className="links">
          <Link to="/home">HOME</Link>
          <Link to="/products">PRODUCTS</Link>
          <Link to="/category">CATEGORIES</Link>
          <Link to="/brand">BRANDS</Link>
        </nav>

        <div className="actions">
          <button
      style={{
        background: "linear-gradient(90deg, #3498db 60%, #007bff 100%)",
        width: "140px",
        height: "40px",
        marginBottom: "18px",
        borderRadius: "8px",
        cursor: "pointer",
        color: "#fff",
        fontWeight: 600,
        fontSize: "15px",
        border: "none",
        boxShadow: "0 2px 8px rgba(0,0,0,0.07)",
        transition: "background 0.2s, transform 0.2s"
      }}
      onClick={() => {
        localStorage.removeItem("token");
        navigate("/login");
      }}
      onMouseEnter={e => e.target.style.background = "linear-gradient(90deg, #2c80b4 60%, #0056b3 100%)"}
      onMouseLeave={e => e.target.style.background = "linear-gradient(90deg, #3498db 60%, #007bff 100%)"}
    >
      LogOut
    </button>
          <img src="/profile.png" alt="Profile" className="profile-icon" />
        </div>
      </header>
    </div>
  );
};

export default Header;
